const patterns = $input.all().map(i => i.json);
if (!patterns.length || !patterns[0].contact_id) return [{ json: { no_data: true } }];

// Group by contact
const contactPatterns = {};
for (const p of patterns) {
  if (!contactPatterns[p.contact_id]) {
    contactPatterns[p.contact_id] = { email: p.email, hours: {}, days: {} };
  }
  const hour = parseInt(p.hour_opened);
  const day = parseInt(p.day_opened);
  const count = parseInt(p.open_count);

  contactPatterns[p.contact_id].hours[hour] = (contactPatterns[p.contact_id].hours[hour] || 0) + count;
  contactPatterns[p.contact_id].days[day] = (contactPatterns[p.contact_id].days[day] || 0) + count;
}

// Calculate optimal send time per contact
const recommendations = [];
for (const [contactId, data] of Object.entries(contactPatterns)) {
  // Find best hour
  const bestHour = Object.entries(data.hours)
    .sort((a, b) => b[1] - a[1])[0];

  // Find best day
  const bestDay = Object.entries(data.days)
    .sort((a, b) => b[1] - a[1])[0];

  const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

  recommendations.push({
    contact_id: parseInt(contactId),
    email: data.email,
    best_hour: parseInt(bestHour?.[0] || 9),
    best_day: parseInt(bestDay?.[0] || 2),
    best_day_name: dayNames[parseInt(bestDay?.[0] || 2)],
    confidence: Math.min(100, Object.values(data.hours).reduce((s, v) => s + v, 0) * 5)
  });
}

return [{ json: {
  total_contacts_analyzed: recommendations.length,
  recommendations: recommendations,
  global_best_hour: getMostCommon(recommendations.map(r => r.best_hour)),
  global_best_day: getMostCommon(recommendations.map(r => r.best_day_name)),
  generated_at: new Date().toISOString()
}}];

function getMostCommon(arr) {
  const counts = {};
  arr.forEach(v => counts[v] = (counts[v] || 0) + 1);
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || 'Tuesday';
}
